target.css:
:root {
  --ink: #17232c;
  --muted: #62737d;
  --surface: #ffffff;
  --navy: #123746;
  --aqua: #2eb9ae;
  --aqua-pale: #dff5f1;
  --line: #d7e3e5;
  --warning: #f4b64a;
  --warning-pale: #fff2d9;
  --track: #c8d7d9;
}

.dispatch-card {
  width: 492px;
  box-sizing: border-box;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--surface);
  color: var(--ink);
}

.dispatch-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 18px 12px;
  border-bottom: 1px solid var(--line);
}

.route-heading {
  display: flex;
  align-items: baseline;
  gap: 10px;
}

.eyebrow {
  margin: 0;
  color: var(--aqua);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1px;
}

.route-heading h1 {
  margin: 0;
  font-size: 19px;
  line-height: 1;
  letter-spacing: -0.4px;
}

.eta-chip {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 7px 10px;
  border-radius: 999px;
  background: var(--aqua-pale);
  color: var(--navy);
  font-size: 12px;
  font-weight: 750;
}

.status-dot {
  width: 7px;
  height: 7px;
  display: inline-block;
  flex: 0 0 auto;
  border-radius: 50%;
  background: var(--aqua);
}

.dashboard-grid {
  display: grid;
  grid-template-columns: 1.18fr 0.82fr;
  gap: 12px;
  padding: 12px 18px 10px;
}

.route-panel,
.cargo-panel {
  min-width: 0;
  box-sizing: border-box;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 11px 12px;
}

.cargo-panel {
  background: var(--navy);
  border-color: var(--navy);
  color: var(--surface);
}

.panel-label {
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.7px;
}

.cargo-panel .panel-label {
  color: var(--aqua);
}

.distance {
  color: var(--ink);
  font-weight: 700;
  letter-spacing: 0;
}

.sensor-tag {
  padding: 3px 5px;
  border-radius: 4px;
  background: var(--aqua);
  color: var(--navy);
  font-size: 9px;
}

.route-track {
  position: relative;
  display: flex;
  justify-content: space-between;
  margin: 17px 4px 11px;
}

.track-line {
  position: absolute;
  top: 6px;
  right: 9px;
  left: 9px;
  height: 2px;
  background: var(--track);
}

.stop {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  color: var(--muted);
  font-size: 9px;
  line-height: 1;
}

.stop b {
  display: grid;
  place-items: center;
  width: 14px;
  height: 14px;
  border: 2px solid var(--surface);
  border-radius: 50%;
  background: var(--track);
  color: var(--surface);
  font-size: 0;
}

.stop small {
  font-size: 9px;
}

.stop.current b {
  width: 18px;
  height: 18px;
  margin-top: -2px;
  background: var(--aqua);
}

.stop.current {
  color: var(--navy);
  font-weight: 800;
}

.stop.destination b {
  background: var(--warning);
}

.route-note {
  margin: 0;
  padding-top: 9px;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 10px;
}

.temperature-readout {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-top: 7px;
}

.temp-value {
  color: var(--surface);
  font-size: 34px;
  font-weight: 800;
  line-height: 0.95;
  letter-spacing: -1.4px;
}

.temp-unit {
  color: var(--aqua);
  font-size: 12px;
  font-weight: 800;
  line-height: 1.05;
}

.temp-unit small {
  color: var(--line);
  font-size: 9px;
  font-weight: 600;
}

.sensor-bars {
  display: flex;
  align-items: end;
  gap: 4px;
  height: 21px;
  margin-top: 10px;
}

.sensor-bar {
  flex: 1;
  border-radius: 3px 3px 1px 1px;
  background: var(--aqua);
}

.bar-one { height: 8px; }
.bar-two { height: 13px; }
.bar-three { height: 17px; }
.bar-four { height: 15px; }
.bar-five { height: 19px; background: var(--warning); }
.bar-six { height: 12px; }

.metric-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  margin: 0 18px;
  border: 1px solid var(--line);
  border-radius: 10px;
  overflow: hidden;
}

.metric {
  padding: 8px 11px;
  border-right: 1px solid var(--line);
}

.metric:last-child {
  border-right: 0;
}

.metric span,
.metric strong {
  display: block;
}

.metric span {
  color: var(--muted);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.7px;
}

.metric strong {
  margin-top: 2px;
  color: var(--navy);
  font-size: 14px;
  line-height: 1;
}

.dispatch-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 18px 12px;
}

.dispatch-footer p {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 0;
  color: var(--muted);
  font-size: 11px;
}

.dispatch-footer .status-dot {
  width: 6px;
  height: 6px;
}

.ack-button {
  border: 0;
  border-radius: 7px;
  padding: 8px 12px;
  background: var(--navy);
  color: var(--surface);
  font-size: 11px;
  font-weight: 750;
  line-height: 1;
}

